import pathlib,sys,hashlib,ast
from collections import Counter
assert len(sys.argv)==6,'master candidateROM SAV output-directory referenceROM (each ROM needs matching .elf)'
master_path,candidate,sav_path,out_path,reference_rom=sys.argv[1:]
master=pathlib.Path(master_path).read_text()
master_sha='efef3b342ff013d131b7aad343aef47d0eab8a0496213203d96c3e3d55852d5e'
assert hashlib.sha256(master.encode()).hexdigest()==master_sha,'regional UI master changed'
assert master.count(' pristine=e.save_state()')==1
prefix=master.split(' pristine=e.save_state()')[0]
out=pathlib.Path(out_path).resolve();out.mkdir(parents=True,exist_ok=False)
reference_sha=hashlib.sha256(pathlib.Path(reference_rom).read_bytes()).hexdigest()
assert pathlib.Path(reference_rom).resolve()!=pathlib.Path(candidate).resolve(),'baseline and candidate must be separate ROMs'
cases=[('tangela',114,96,7,0x4011),('sneasel',215,114,7,0x4000),('dratini',147,120,1,0x4000)]
def chunks(raw):
 assert len(raw)%4==0
 return Counter(raw[i:i+4] for i in range(0,len(raw),4))
reference={}
baseline_tail=" pristine=e.save_state()\n protected=[(e.sym('gPlayerParty'),600),(e.ptr('gSaveBlock1Ptr'),15720),(e.ptr('gSaveBlock2Ptr'),3876),(e.ptr('gPokemonStoragePtr'),33744)]\n protected_bytes=[e.read(p,n) for p,n in protected]\n arena=0\n try:\n  region(0);call('EnableNationalPokedex')\n  arena=call('Alloc',528);assert 0x02000000<=arena<=0x0201c000-528\n  guards=b'HABITAT-QA-GUARD';e.write(arena,guards);e.write(arena+496,guards);e.write(arena+512,bytes(16))\n  for name,national,x,y,attr in cases:\n   sp=call('NationalPokedexNumToSpecies',national)\n   assert call('SpeciesToNationalPokedexNum',sp)==national\n   mask=call('GetSpeciesPokedexAreaRegions',sp,arena+512)\n   sevii=call('GetUnlockedSeviiAreas')|e.u8(arena+512)\n   markers={}\n   for rr in range(3):\n    n=call('GetSpeciesPokedexAreaMarkers',sp,arena+16,rr,sevii);assert 0<=n<=120\n    markers[rr]=e.read(arena+16,n*4).hex()\n    assert e.read(arena,16)==guards and e.read(arena+496,16)==guards\n   reference[name]=dict(national=national,species=sp,mask=mask,sevii=sevii,markers=markers)\n  call('Free',arena);arena=0\n finally:\n  e.load_state(pristine)\n  assert all(e.read(p,n)==v for (p,n),v in zip(protected,protected_bytes)),'baseline original RAM records not restored'\nafter=saves();after[str(sav)]=h(sav.read_bytes());assert after==old,'original baseline SAV changed'\n"
candidate_tail=" pristine=e.save_state()\n protected=[(e.sym('gPlayerParty'),600),(e.ptr('gSaveBlock1Ptr'),15720),(e.ptr('gSaveBlock2Ptr'),3876),(e.ptr('gPokemonStoragePtr'),33744)]\n protected_bytes=[e.read(p,n) for p,n in protected]\n rows=[];arena=0\n try:\n  region(0)\n  for n in range(1,387):call('GetSetPokedexFlag',n,2);call('GetSetPokedexFlag',n,3)\n  call('EnableNationalPokedex');assert call('IsNationalPokedexEnabled')\n  base=e.save_state()\n  for name,national,x,y,attr in cases:\n   e.load_state(base);pages=[];visited=[];rendered={};marker_sid=None\n   call('CB2_OpenPokedexFromStartMenu');wait('Task_PokedexScreen',6)\n   for _ in range(24):\n    tid=e.u8(dex()+23);assert tid<16\n    lm=sy['gTasks']+40*tid+8;ix=e.u16(lm+24)+e.u16(lm+26)\n    if e.u32(e.u32(lm)+8*ix+4)==14:e.press('A');break\n    e.press('DOWN')\n   else:raise AssertionError('native national menu missing')\n   p=wait('Task_DexScreen_NumericalOrder',6)\n   assert e.u8(p+66)==5 and e.u8(p+111) and e.u16(p+72)==386\n   tid=e.u8(p+65);assert tid<16;lm=sy['gTasks']+40*tid+8\n   call('ListMenuChangeSelection',lm,1,national-1,1);e.run(24)\n   assert e.u16(lm+24)+e.u16(lm+26)==national-1,'native list selection did not advance'\n   e.press('A');p=wait('Task_DexScreen_ShowMonPage',5)\n   sp=e.u16(p+90);assert call('SpeciesToNationalPokedexNum',sp)==national,(name,'wrong detail species')\n   assert sp==reference[name]['species']\n   e.press('A');p=wait('Task_DexScreen_ShowMonPage',9)\n   arena=call('Alloc',528);assert 0x02000000<=arena<=0x0201c000-528\n   guards=b'HABITAT-QA-GUARD';e.write(arena,guards);e.write(arena+496,guards);e.write(arena+512,bytes(16))\n   mask=call('GetSpeciesPokedexAreaRegions',sp,arena+512)\n   assert mask==reference[name]['mask']|4,(name,'unexpected area region delta',mask)\n   initial=e.u8(p+101)\n   for turn in range(4):\n    p=dex();rr=e.u8(p+101)\n    assert rr in (0,1,2) and e.u16(p+90)==sp and e.u8(p+1)==9\n    assert e.u8(p+100)==reference[name]['sevii'],'unrelated Sevii area change'\n    mt=e.u8(p+4);assert mt<16\n    ta=sy['gTasks']+40*mt;assert e.u8(ta+4) and e.u32(ta)&~1==sy['Task_ShowAreaMarkers']\n    m=ta+8;buf=e.u32(m+8);assert buf==e.u32(m+4)\n    count=call('GetNumPokedexAreaMarkers',mt);assert count==e.u8(m) and 0<=count<=120\n    assert 0x02000000<=buf<=0x0201c000-480 and e.u16(buf-14)==0xa3a3 and e.u32(buf-12)>=480\n    n=call('GetSpeciesPokedexAreaMarkers',sp,arena+16,rr,e.u8(p+100))\n    raw=e.read(arena+16,n*4)\n    assert n==count and raw==e.read(buf,n*4),'rendered/native marker bytes differ'\n    assert e.read(arena,16)==guards and e.read(arena+496,16)==guards,'marker arena overflow'\n    sid=e.u8(m+13);assert sid<64;marker_sid=sid\n    sprite=sy['gSprites']+68*sid;flags=e.u16(sprite+0x3e)\n    assert flags&1 and not flags&4 and e.u32(sprite+0x18)==m,'invalid or hidden marker sprite'\n    nt=sum(bool(e.u8(sy['gTasks']+40*j+4)) and e.u32(sy['gTasks']+40*j)&~1==sy['Task_ShowAreaMarkers'] for j in range(16))\n    assert nt==1,'area marker task leak'\n    baseline_raw=bytes.fromhex(reference[name]['markers'][rr])\n    if rr in (0,1):assert raw==baseline_raw,(name,rr,'existing Kanto/Hoenn marker bytes changed')\n    else:\n     expected=struct.pack('<bbH',x,y,attr)\n     assert chunks(raw)==chunks(baseline_raw)+Counter([expected]),(name,'expected old Johto markers plus exactly one new marker')\n     for _,_,other_x,other_y,other_attr in cases:\n      other=struct.pack('<bbH',other_x,other_y,other_attr)\n      if other!=expected:assert chunks(raw)[other]==chunks(baseline_raw)[other],(name,'unexpected other new marker')\n    win=e.u8(p+74);assert win<32\n    wa=sy['gWindows']+12*win;wd=e.u8(wa+3);ht=e.u8(wa+4);pix=e.u32(wa+8)\n    assert 0<wd<=32 and 0<ht<=32 and 0x02000000<=pix<=0x02040000-wd*ht*32\n    if turn<3:\n     assert rr not in visited;visited.append(rr);rendered[rr]=raw\n     e.shot(str(out/(name+'-region-'+str(rr)+'.png')))\n     page=dict(region=rr,markers=count,marker_tasks=nt,marker_sprite=sid,marker_bytes_sha256=h(raw),map_window=[wd,ht],map_pixels_sha256=h(e.read(pix,wd*ht*32)))\n     pages.append(page)\n    else:assert rr==initial and raw==rendered[rr],'SELECT cycle failed to restore markers'\n    if turn<3:e.press('SELECT');e.run(24)\n   assert set(visited)=={0,1,2}\n   call('Free',arena);arena=0\n   e.press('B');wait('Task_DexScreen_ShowMonPage',5)\n   assert task('Task_ShowAreaMarkers') is None,'marker task remained after closing area page'\n   row=dict(name=name,national=national,species=sp,pages=pages,select_cycle=True,new_johto_marker=[x,y,attr],new_marker_count=1,other_new_marker_delta=0,old_kanto_hoenn_bytes_preserved=True,old_johto_markers_preserved=True,area_close_cleanup=True)\n   rows.append(row);emit('blackthorn_native_habitat',row)\n  result=dict(all_pass=True,rom_sha256=h(rb),reference_rom_sha256=reference_sha,master_sha256=master_sha,original_sav_sha256=h(sav.read_bytes()),cases=rows,temporary_native_ram_fixture=True,native_battery_save_performed=False,actual_device_fps_measured=False)\n finally:\n  e.load_state(pristine)\n  assert all(e.read(p,n)==v for (p,n),v in zip(protected,protected_bytes)),'original RAM Pokemon/save records not restored'\n  emit('original_runtime_records_restored',True)\nafter=saves();after[str(sav)]=h(sav.read_bytes());assert after==old,'original SAV changed'\nresult['original_saves_preserved']=True\n(out/'result.json').write_text(json.dumps(result,indent=2));emit('blackthorn_native_habitat_result',result)\n"
sys.argv=[sys.argv[0],reference_rom,sav_path]
exec(compile(prefix+baseline_tail,'blackthorn-habitat-reference','exec'))
assert set(reference)=={c[0] for c in cases}
sys.argv=[sys.argv[0],candidate,sav_path]
exec(compile(prefix+candidate_tail,'blackthorn-habitat-candidate','exec'))
